atus": "draft", "id": "12bc4ede-97fa-5270-b74a-fcff7f7d4d5f", "subject_id": "93cf2174-599f-5597-92dd-1408fa0b3bf9", "source_id": "c04df55c-ddd9-5a0c-b5e2-e576f907b8f7"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "915年七月澶州被晋军攻取后", "citation": "卷269·贞明元年（915）·zztj-v269-y0915-p015·原文件第44行", "note": "原文：晋王以魏州将李岩为澶州刺史。；核对说明：按主书段落次序；未把干支换算成公历日。", "status": "draft", "id": "457bb4c6-63f1-5d7e-9a57-b9cbd46f501a", "subject_id": "93cf2174-599f-5597-92dd-1408fa0b3bf9", "source_id": "c04df55c-ddd9-5a0c-b5e2-e576f907b8f7"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李存勖：任命李岩的晋王。", "citation": "卷269·贞明元年（915）·zztj-v269-y0915-p015·原文件第44行", "note": "原文：晋王以魏州将李岩为澶州刺史。；核对说明：参与身份依据本段措辞，不因同场出现推定其他关系。", "status": "draft", "id": "ddd915f3-1e3d-5a2a-a347-cdd44bac0b49", "subject_id": "c47d7daa-e11c-5e37-abfb-8a3cd492cbfb", "source_id": "c04df55c-ddd9-5a0c-b5e2-e576f907b8f7"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李岩：魏州将，获任澶州刺史。", "citation": "卷269·贞明元年（915）·zztj-v269-y0915-p015·原文件第44行", "note": "原文：晋王以魏州将李岩为澶州刺史。；核对说明：姓名按既有主体规范；原文和摘录保留底本字形。", "status": "draft", "id": "d1a1eefc-7801-56d1-a7ee-6306f248270c", "subject_id": "37d2dab9-5ef1-58de-bc85-20a535087751", "source_id": "c04df55c-ddd9-5a0c-b5e2-e576f907b8f7"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李岩：魏州将，获任澶州刺史。", "citation": "卷269·贞明元年（915）·zztj-v269-y0915-p015·原文件第44行", "note": "原文：晋王以魏州将李岩为澶州刺史。；核对说明：参与身份依据本段措辞，不因同场出现推定其他关系。", "status": "draft", "id": "d39ee5b2-87d1-5ff0-b4da-447dc3254c96", "subject_id": "0cecc322-ef26-564d-bede-458c2fea6691", "source_id": "c04df55c-ddd9-5a0c-b5e2-e576f907b8f7"}, {"subject_table": "event", "field_path": "description", "claim_text": "刘鄩伏兵围晋王，夏鲁奇力战，符存审援军解围。", "citation": "卷269·贞明元年（915）·zztj-v269-y0915-p016·原文件第45行", "note": "原文：晋王劳军于魏县，因帅百馀骑循河而上，觇刘鄩营。会天阴晦，鄩伏兵五千于河曲丛林间，鼓噪而出，围王数重。王跃马大呼，帅骑驰突，所向披靡。裨将夏鲁奇等操短兵力战，自午至申乃得出，亡其七骑，鲁奇手杀百馀人，伤夷遍体，会李存审救兵至，乃得免。；核对说明：主书记伏兵五千、晋王损失七骑及夏鲁奇手杀百余；这些数字不